import { BUILDINGS, VEHICLES, ITEMS } from './catalog.js';
import { reachable } from './world.js';


/** Nur lesende Zuordnung. Exportiert für unabhängige Darstellungsprüfungen. */
export function vehicleActivity(state,v){
  const candidates=[['tour',state?.tours,v.tour||v.shipment],['freight',state?.freights,v.freight||v.shipment],['transfer',state?.transfers,v.shipment],['service',state?.returns,v.shipment],['shipment',state?.shipments,v.shipment]];
  for(const [kind,list,id] of candidates){const task=list?.find(t=>t.id===id||(v.status===kind&&t.vehicleId===v.id&&!['complete','cancelled','repaired','recycled','decision','inspection'].includes(t.status)));if(task)return {task,kind,status:task.status};}
  return {task:v.maintenance,kind:v.status,status:v.status};
}
export function coldWarnings(state,site){return (state?.batches||[]).filter(b=>b.site===site&&b.qty!==0&&ITEMS[b.item]?.cold&&b.location!=='vehicle'&&(b.blocked||b.locked||b.coldDamaged||b.temperature>8||b.quality<75));}
export function vehicleAtSite(state,v,site){if(v.status==='rentalReturned')return false;const a=vehicleActivity(state,v);if(['transit','returning','collecting','linehaul','outbound','inbound'].includes(a.status))return false;if(['shipment','tour','freight'].includes(a.kind)&&a.status==='unloading')return false;return (a.kind==='transfer'&&a.status==='unloading'?a.task.toSite:v.site)===site;}

